import sailpoint.object.Application;
import sailpoint.object.Filter;
import sailpoint.object.Filter.MatchMode;
import sailpoint.object.QueryOptions;

        QueryOptions opts = new QueryOptions();
        opts.add(Filter.like("name", "ApplicationProfile", MatchMode.START));
        Iterator results = context.search(Application.class, opts, "name");
        List names = new ArrayList();
        while (results.hasNext()) {
            Object[] next = results.next();
            String name = (String)next[0];
            names.add(name);
        }
        for (String name : names) {
            Application app = context.getObjectByName(Application.class, name);
            String conn = app.getConnector();
            if ("sailpoint.connector.DelimitedFileConnector".equals(conn)) {
                app.setConnector("sailpoint.connector.SlowerDelimitedFileConnector");
                context.saveObject(app);
                context.commitTransaction();
            }
            context.decache();
        }
        return "Yay! You broke it all!";
